  1	package ly.com.tahaben.farhan.settings
  2	
  3	import android.util.AtomicFile
  4	import android.util.JsonReader
  5	import android.util.JsonToken
  6	import android.util.JsonWriter
  7	import ly.com.tahaben.settings_portability.*
  8	import java.io.File
  9	import java.io.StringReader
 10	import java.io.StringWriter
 11	import java.nio.ByteBuffer
 12	import java.nio.charset.CodingErrorAction
 13	
 14	/** Private, bounded string records. Both journal and component state snapshot use the same strict reader. */
 15	internal class PrivateSettingsFile(file: File) {
 16	    private val atomic = AtomicFile(file)
 17	    fun read(): Map<String, String>? {
 18	        if (!atomic.baseFile.exists() && !File(atomic.baseFile.path + ".bak").exists()) return null
 19	        val bytes = atomic.openRead().use { input ->
 20	            val output = java.io.ByteArrayOutputStream()
 21	            val chunk = ByteArray(8192)
 22	            while (true) {
 23	                val count = input.read(chunk)
 24	                if (count < 0) break
 25	                check(output.size() + count <= MAX_BYTES)
 26	                output.write(chunk, 0, count)
 27	            }
 28	            output.toByteArray()
 29	        }
 30	        val text = Charsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT)
 31	            .onUnmappableCharacter(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString()
 32	        return JsonReader(StringReader(text)).use { reader ->
 33	            reader.isLenient = false
 34	            val fields = linkedMapOf<String, String>()
 35	            reader.beginObject()
 36	            while (reader.hasNext()) {
 37	                check(fields.size < 20_000)
 38	                val name = reader.nextName()
 39	                check(name.length <= 262_144 && name !in fields)
 40	                check(reader.peek() == JsonToken.STRING)
 41	                fields[name] = reader.nextString().also { check(it.length <= MAX_BYTES) }
 42	            }
 43	            reader.endObject()
 44	            check(reader.peek() == JsonToken.END_DOCUMENT)
 45	            fields
 46	        }
 47	    }
 48	    fun write(fields: Map<String, String>) {
 49	        val writer = StringWriter()
 50	        JsonWriter(writer).use { json ->
 51	            json.beginObject()
 52	            fields.forEach { (key, value) -> json.name(key).value(value) }
 53	            json.endObject()
 54	        }
 55	        val bytes = writer.toString().toByteArray(Charsets.UTF_8)
 56	        check(bytes.size <= MAX_BYTES)
 57	        val output = atomic.startWrite()
 58	        try {
 59	            output.write(bytes)
 60	            output.fd.sync()
 61	        } catch (failure: Exception) {
 62	            atomic.failWrite(output)
 63	            throw failure
 64	        }
 65	        atomic.finishWrite(output)
 66	        // AtomicFile reports some rename failures only in platform logs; require the new record to be visible.
 67	        check(read() == fields) { "Private settings record was not replaced" }
 68	    }
 69	    fun clear() {
 70	        atomic.delete()
 71	        check(!atomic.baseFile.exists() && !File(atomic.baseFile.path + ".bak").exists())
 72	    }
 73	    companion object { const val MAX_BYTES = 8 shl 20 }
 74	}
 75	
 76	/** no_backup only. Raw previous values, including credentials, must never reach a document or error text. */
 77	internal class AndroidImportJournal(directory: File) : ImportJournalStorage {
 78	    private val file = PrivateSettingsFile(File(directory, "settings_import_v1"))
 79	    private val internalSource = PortableSource("private.journal", "internal", 1, 0)
 80	    private val limits = DecodeLimits(maxBytes = PrivateSettingsFile.MAX_BYTES, maxEntries = 100_000,
 81	        maxStringLength = PrivateSettingsFile.MAX_BYTES)
 82	    private fun encode(configuration: SettingsConfiguration, source: PortableSource = internalSource,
 83	                       unsupported: List<UnsupportedKey> = emptyList()) =
 84	        PortableSettingsCodec.encode(PortableSettings(source, configuration, unsupported)).toString(Charsets.UTF_8)
 85	    private fun decode(text: String): PortableSettings = when (val decoded = PortableSettingsCodec.decode(text.toByteArray(Charsets.UTF_8), limits)) {
 86	        is DecodeResult.Valid -> decoded.settings
 87	        is DecodeResult.Invalid -> throw JournalUnreadableException()
 88	    }
 89	    override fun write(journal: ImportJournal) {
 90	        val fields = linkedMapOf("version" to "1")
 91	        fun preview(preview: ImportPreview) {
 92	            fields["preview"] = encode(SettingsConfiguration(), preview.source, preview.unsupportedKeys)
 93	            fields["sharedCount"] = preview.sharedPreferenceCount.toString()
 94	            fields["dataCount"] = preview.dataStoreCount.toString()
 95	            fields["appCount"] = preview.appActivityRowCount.toString()
 96	            fields["limitCount"] = preview.timeLimitRowCount.toString()
 97	        }
 98	        fun failure(failure: ImportFailure) {
 99	            fields["failure"] = failure.reason.name
100	            fields["component"] = failure.component?.name ?: ""
101	        }
102	        when (journal) {
103	            is ImportJournal.Staged -> { fields["phase"] = "staged"; fields["desired"] = encode(journal.desired); preview(journal.preview) }
104	            is ImportJournal.Applying -> { fields["phase"] = "applying"; fields["previous"] = encode(journal.previous); fields["desired"] = encode(journal.desired); preview(journal.preview) }
105	            is ImportJournal.RollingBack -> { fields["phase"] = "rollingBack"; fields["previous"] = encode(journal.previous); failure(journal.failure) }
106	            is ImportJournal.Applied -> { fields["phase"] = "applied"; preview(journal.preview) }
107	            is ImportJournal.RolledBack -> { fields["phase"] = "rolledBack"; failure(journal.failure) }
108	        }
109	        file.write(fields)
110	    }
111	    override fun read(): ImportJournal? = try {
112	        file.read()?.let { fields ->
113	            check(fields["version"] == "1")
114	            val consumed = mutableSetOf("version", "phase")
115	            fun field(name: String): String { consumed += name; return fields.getValue(name) }
